import base64
import binascii
import os
import time
from typing import Union, Optional, Tuple, Iterable, Any

from cryptography import utils
from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes, padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.hmac import HMAC


class InvalidToken(Exception):
    """Raised when a token cannot be decrypted or verified."""
    pass


_MAX_CLOCK_SKEW = 60


class Fernet:
    """
    Symmetric authenticated cryptography using AES-CBC and HMAC-SHA256.
    """

    def __init__(self, key: Union[bytes, str], backend: Any = None) -> None:
        try:
            key_bytes = base64.urlsafe_b64decode(key)
        except binascii.Error as exc:
            raise ValueError(
                "Fernet key must be 32 url-safe base64 encoded bytes"
            ) from exc

        if len(key_bytes) != 32:
            raise ValueError(
                "Fernet key must be 32 url-safe base64 encoded bytes"
            )

        self._signing_key = key_bytes[:16]
        self._encryption_key = key_bytes[16:]

    @classmethod
    def generate_key(cls) -> bytes:
        """Generate a new Fernet key."""
        return base64.urlsafe_b64encode(os.urandom(32))

    def encrypt(self, data: bytes) -> bytes:
        return self.encrypt_at_time(data, int(time.time()))

    def encrypt_at_time(self, data: bytes, current_time: int) -> bytes:
        iv = os.urandom(16)
        return self._encrypt(data, current_time, iv)

    def _encrypt(self, data: bytes, timestamp: int, iv: bytes) -> bytes:
        utils._check_bytes("data", data)

        # Padding
        padder = padding.PKCS7(algorithms.AES.block_size).padder()
        padded = padder.update(data) + padder.finalize()

        # AES Encryption
        encryptor = Cipher(
            algorithms.AES(self._encryption_key),
            modes.CBC(iv)
        ).encryptor()

        ciphertext = encryptor.update(padded) + encryptor.finalize()

        # Token structure
        token_body = (
            b"\x80"
            + timestamp.to_bytes(8, "big")
            + iv
            + ciphertext
        )

        # HMAC authentication
        h = HMAC(self._signing_key, hashes.SHA256())
        h.update(token_body)
        signature = h.finalize()

        return base64.urlsafe_b64encode(token_body + signature)

    def decrypt(self, token: Union[bytes, str], ttl: Optional[int] = None) -> bytes:
        timestamp, data = self._extract_token(token)

        time_info = None
        if ttl is not None:
            time_info = (ttl, int(time.time()))

        return self._decrypt(data, timestamp, time_info)

    def decrypt_at_time(
        self,
        token: Union[bytes, str],
        ttl: int,
        current_time: int
    ) -> bytes:
        if ttl is None:
            raise ValueError("ttl must not be None")

        timestamp, data = self._extract_token(token)
        return self._decrypt(data, timestamp, (ttl, current_time))

    def extract_timestamp(self, token: Union[bytes, str]) -> int:
        timestamp, data = self._extract_token(token)
        self._verify_signature(data)
        return timestamp

    @staticmethod
    def _extract_token(token: Union[bytes, str]) -> Tuple[int, bytes]:
        if not isinstance(token, (bytes, str)):
            raise TypeError("token must be bytes or str")

        try:
            decoded = base64.urlsafe_b64decode(token)
        except (TypeError, binascii.Error):
            raise InvalidToken

        if not decoded or decoded[0] != 0x80 or len(decoded) < 9:
            raise InvalidToken

        timestamp = int.from_bytes(decoded[1:9], "big")
        return timestamp, decoded

    def _verify_signature(self, data: bytes) -> None:
        h = HMAC(self._signing_key, hashes.SHA256())
        h.update(data[:-32])

        try:
            h.verify(data[-32:])
        except InvalidSignature:
            raise InvalidToken

    def _decrypt(
        self,
        data: bytes,
        timestamp: int,
        time_info: Optional[Tuple[int, int]],
    ) -> bytes:

        if time_info:
            ttl, current_time = time_info

            if timestamp + ttl < current_time:
                raise InvalidToken

            if current_time + _MAX_CLOCK_SKEW < timestamp:
                raise InvalidToken

        self._verify_signature(data)

        iv = data[9:25]
        ciphertext = data[25:-32]

        decryptor = Cipher(
            algorithms.AES(self._encryption_key),
            modes.CBC(iv)
        ).decryptor()

        padded = decryptor.update(ciphertext) + decryptor.finalize()

        unpadder = padding.PKCS7(algorithms.AES.block_size).unpadder()
        plaintext = unpadder.update(padded) + unpadder.finalize()

        return plaintext


class MultiFernet:
    """
    Allows key rotation by trying multiple Fernet keys.
    """

    def __init__(self, fernets: Iterable[Fernet]):
        self._fernets = list(fernets)

        if not self._fernets:
            raise ValueError("MultiFernet requires at least one Fernet key")

    def encrypt(self, msg: bytes) -> bytes:
        return self._fernets[0].encrypt(msg)

    def encrypt_at_time(self, msg: bytes, current_time: int) -> bytes:
        return self._fernets[0].encrypt_at_time(msg, current_time)

    def rotate(self, token: Union[bytes, str]) -> bytes:
        timestamp, data = Fernet._extract_token(token)

        for f in self._fernets:
            try:
                plaintext = f._decrypt(data, timestamp, None)
                break
            except InvalidToken:
                continue
        else:
            raise InvalidToken

        iv = os.urandom(16)
        return self._fernets[0]._encrypt(plaintext, timestamp, iv)

    def decrypt(self, token: Union[bytes, str], ttl: Optional[int] = None) -> bytes:
        for f in self._fernets:
            try:
                return f.decrypt(token, ttl)
            except InvalidToken:
                continue

        raise InvalidToken

    def decrypt_at_time(
        self,
        token: Union[bytes, str],
        ttl: int,
        current_time: int,
    ) -> bytes:

        for f in self._fernets:
            try:
                return f.decrypt_at_time(token, ttl, current_time)
            except InvalidToken:
                continue

        raise InvalidToken